            tally.posted++;
        } catch (e) {
            console.warn('Failed to reply to comment #' + item.inReplyToId + ':', e);
        }
    } else if (replyText) {
        console.log('Skipping reply for thread without rootCommentId — would become a generic issue comment');
    }

    if (item.threadId) {
        try {
